/* Distribution des pertes — EL, capital & risque extrême */
(function () {
  var svg = document.getElementById("ll-chart");
  if (!svg) return;
  var LV = [90, 95, 97.5, 99, 99.9];
  var Z  = {90:1.2816, 95:1.6449, 97.5:1.9600, 99:2.3263, 99.9:3.0902};
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }

  function draw() {
    var el=v("ll-el"), sig=v("ll-sig"), ci=Math.round(v("ll-c"));
    var conf=LV[ci], z=Z[conf];
    setT("ll-el-o", v("ll-el")+"%"); setT("ll-sig-o", v("ll-sig")+"%");
    setT("ll-c-o", (conf%1===0?conf.toFixed(0):conf.toFixed(1))+"%");
    var varv=el+z*sig, ul=z*sig;
    setT("ll-oel", el.toFixed(2)+"%"); setT("ll-ovar", varv.toFixed(2)+"%"); setT("ll-oul", ul.toFixed(2)+"%");

    var W=520,H=260,L=16,R=16,T=14,B=34, pw=W-L-R, ph=H-T-B;
    var xmin=Math.min(0, el-3*sig), xmax=el+3.6*sig;
    function px(x){ return L + (x-xmin)/(xmax-xmin)*pw; }
    function pdf(x){ return Math.exp(-0.5*Math.pow((x-el)/sig,2)); }
    var ymax=1; function py(y){ return T + (1-y/ymax)*ph; }

    var N=120, pts=[];
    for (var i=0;i<=N;i++){ var x=xmin+(xmax-xmin)*i/N; pts.push({x:x,y:pdf(x)}); }
    function area(xa,xb,fill){
      var s='M '+px(xa).toFixed(1)+','+py(0).toFixed(1)+' ';
      for (var i=0;i<=N;i++){ var x=pts[i].x; if(x<xa-1e-9)continue; if(x>xb+1e-9)break; s+='L '+px(x).toFixed(1)+','+py(pts[i].y).toFixed(1)+' '; }
      s+='L '+px(Math.min(xb,xmax)).toFixed(1)+','+py(0).toFixed(1)+' Z';
      return '<path d="'+s+'" fill="'+fill+'"/>';
    }
    var g="";
    g+=area(xmin, el, "rgba(47,143,106,0.55)");     // provisions (green) up to EL
    g+=area(el, varv, "rgba(193,154,62,0.55)");      // capital (gold) EL..VaR
    g+=area(varv, xmax, "rgba(178,58,72,0.55)");     // tail (crimson) beyond VaR
    // curve outline
    var poly=""; for (var j=0;j<pts.length;j++) poly+=px(pts[j].x).toFixed(1)+","+py(pts[j].y).toFixed(1)+" ";
    g+='<polyline points="'+poly.trim()+'" fill="none" stroke="var(--teal)" stroke-width="2.4"/>';
    // baseline
    g+='<line class="axis" x1="'+L+'" y1="'+py(0)+'" x2="'+(L+pw)+'" y2="'+py(0)+'"/>';
    // EL & VaR vertical lines
    g+='<line class="vline" x1="'+px(el)+'" y1="'+T+'" x2="'+px(el)+'" y2="'+py(0)+'" stroke="#2f8f6a"/>';
    g+='<text class="lab" x="'+px(el)+'" y="'+(T+10)+'" text-anchor="middle" fill="#2f8f6a">EL</text>';
    g+='<line class="vline" x1="'+px(varv)+'" y1="'+T+'" x2="'+px(varv)+'" y2="'+py(0)+'" stroke="var(--crimson)"/>';
    g+='<text class="lab" x="'+px(varv)+'" y="'+(T+10)+'" text-anchor="middle" fill="var(--crimson)">VaR</text>';
    // x axis ticks
    g+='<text class="tick" x="'+L+'" y="'+(H-16)+'" text-anchor="start">'+xmin.toFixed(0)+'%</text>';
    g+='<text class="tick" x="'+(L+pw)+'" y="'+(H-16)+'" text-anchor="end">'+xmax.toFixed(0)+'%</text>';
    g+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+ (document.body.getAttribute("data-active-lang")==="en"?"loss (% of exposure)":(document.body.getAttribute("data-active-lang")==="nl"?"verlies (% blootstelling)":"perte (% de l'exposition)")) +'</text>';
    svg.innerHTML=g;
  }

  ["ll-el","ll-sig","ll-c"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
